// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(address(this) != address(0));

        address initialOwner = c.owner();
        vm.assume(initialOwner == address(0));

        vm.prank(address(0));
        c.transferOwnership(address(this));

        assertTrue(c.owner() == address(this));

        vm.prank(address(this));
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
